package com.logatron.contracts.ingestion;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class ContractCompatibilityTest {private final ObjectMapper json=new ObjectMapper().registerModule(new JavaTimeModule()).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 @Test void rawV1RoundTripsAndIgnoresFutureOptionalFields()throws Exception{RawLogEnvelope input=new RawLogEnvelope(1,UUID.randomUUID(),Instant.parse("2026-08-27T00:00:00Z"),new RawLogEnvelope.Collector("collector","offset"),new RawLogEnvelope.Resource(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID()),new RawLogEnvelope.Source(UUID.randomUUID(),"/logs/app.log","application",ParserProfile.JSON),"{\"message\":\"hello\"}",Map.of());String wire=json.writeValueAsString(input).replaceFirst("\\{","{\"futureOptional\":true,");assertThat(json.readValue(wire,RawLogEnvelope.class)).isEqualTo(input);}
 @Test void allV1ContractsCarrySchemaVersion(){assertThat(RawLogEnvelope.class.getRecordComponents()).extracting(java.lang.reflect.RecordComponent::getName).contains("schemaVersion");assertThat(CanonicalLogEvent.class.getRecordComponents()).extracting(java.lang.reflect.RecordComponent::getName).contains("schemaVersion");assertThat(DeadLetterEvent.class.getRecordComponents()).extracting(java.lang.reflect.RecordComponent::getName).contains("schemaVersion");}
 @Test void schemasArePackaged(){for(String name:List.of("raw-log-envelope-v1.schema.json","canonical-log-event-v1.schema.json","dead-letter-event-v1.schema.json"))assertThat(getClass().getResource("/schemas/"+name)).isNotNull();}
}